      "intro": "让观点不只停留在文本中，而是转化为观众能够进入、行走和感知的空间体验。策展实践连接艺术研究、内容策划、视觉传播与现场执行，广泛应用于美术馆、商业策展、品牌快闪、公共文化与文旅项目。",
