          "n": "01",
          "t": "行业解读",
          "kind": "prose",
          "body": [
            "艺术疗愈并不是简单的[[“画画放松”]]。专业艺术治疗是在治疗关系中，综合运用艺术创作、创造过程与心理学理论，支持个体的情绪表达、认知发展和身心健康。",
            "在临床路径之外，艺术还可以进入学校、社区、博物馆、养老机构与企业健康项目，形成非临床的创造性健康服务。行业核心不是完成一件漂亮作品，而是依据真实人群需求，设计有目标、有伦理边界、可记录且可评估的艺术介入过程。"
          ],
          "note": "专业边界：临床艺术治疗通常需要研究生层级教育、受督导实践与相应地区认证；普通艺术工作坊不能替代临床专业训练。"
