            "荣获纽约艺术基金会/纽约州艺术委员会（NYFA/NYSCA）奖学金和雷·马特·惠曼基金会新锐艺术家奖。",
            "作品和项目被《纽约时报》、《纽约客》（The New Yorker）、《BOMB》等全球顶级媒体多次报道评述。",
            "在纽约文化地标布鲁克林音乐学院（BAM）中，她创造了一个沉浸式装置，用绚丽的图案和织物重新定义了建筑内部空间，使其像一个巨大的、可穿行的身体器官，探索了公共空间的功能性、记忆与感官体验之间的关系。"
