            "个人作品展遍布纽约、费城、柏林和斯科普里等地，包括美国国家版画中心（The Print Center）个展，影响力跨越两大西洋两岸。",
            "《Between Two Lands》（双生之地）通过绘画与雕塑的结合，探讨了同时身处美国费城与马其顿比托拉两地的双重身份体验，视觉化地呈现了记忆与归属之间的张力与诗意。"
