          "fit": "希望在国际化环境中关注亚洲文化、跨文化交流或创意产业，同时保持较强学术基础和作品实践的学生。",
          "focus": "以区域文化经验形成研究问题，再以国际化的视觉语言、工作室实践和展示能力进入更广阔的艺术网络。",
          "material": "成绩与课程、作品集、个人陈述/面试，以及能够体现区域观察、实践和跨文化理解的项目过程。",
          "outcome": "跨文化表达、策展/展示、创作实践、行业协作与区域艺术网络意识。",
